# Function to check if cell (r,c) is between two 9s in its row or column
def is_between_9s(grid, r, c):
    # Check row
    row = grid[r]
    left_has_9 = False
    right_has_9 = False
    for col in range(c):
        if row[col] == 9:
            left_has_9 = True

    for col in range(c+1, len(row)):
        if row[col] == 9:
            right_has_9 = True

    if left_has_9 and right_has_9:
        return True

    # Check column
    col = [grid[i][c] for i in range(len(grid))]
    top_has_9 = False
    bottom_has_9 = False
    for i in range(r):
        if col[i] == 9:
            top_has_9 = True

    for i in range(r+1, len(col)):
        if col[i] == 9:
            bottom_has_9 = True

    if top_has_9 and bottom_has_9:
        return True

    return False

