import json

def transform_v1(grid):
    """
    Rule: A 4 becomes 2 if there's a 9 at distance ≤2 and a 9 at distance >0
    in the same row or column (i.e., between 9s in some direction).
    """
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                became_2 = False

                # Check left
                for dc in range(1, 100):
                    if c - dc < 0:
                        break
                    if grid[r][c - dc] == 9:
                        became_2 = True
                        break

                if not became_2:
                    # Check right
                    for dc in range(1, 100):
                        if c + dc >= w:
                            break
                        if grid[r][c + dc] == 9:
                            became_2 = True
                            break

                if not became_2:
                    # Check up
                    for dr in range(1, 100):
                        if r - dr < 0:
                            break
                        if grid[r - dr][c] == 9:
                            became_2 = True
                            break

                if not became_2:
                    # Check down
                    for dr in range(1, 100):
                        if r + dr >= h:
                            break
                        if grid[r + dr][c] == 9:
                            became_2 = True
                            break

                if became_2:
                    result[r][c] = 2

    return result

