import json

def transform_rule(grid):
    """
    Rule: A 4 becomes 2 if it's between two 9s horizontally OR vertically.
    "Between" means there's at least one 9 in each direction from the cell.
    """
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                became_2 = False

                # Check horizontal: 9 on both left and right
                has_9_left = False
                for dc in range(1, w):
                    if c - dc < 0:
                        break
                    if grid[r][c - dc] == 9:
                        has_9_left = True

                if has_9_left:
                    has_9_right = False
                    for dc in range(1, w):
                        if c + dc >= w:
                            break
                        if grid[r][c + dc] == 9:
                            has_9_right = True

                    if has_9_right:
                        result[r][c] = 2
                        became_2 = True

                if not became_2:
                    # Check vertical: 9 on both up and down
                    has_9_up = False
                    for dr in range(1, h):
                        if r - dr < 0:
                            break
                        if grid[r - dr][c] == 9:
                            has_9_up = True

                    if has_9_up:
                        has_9_down = False
                        for dr in range(1, h):
                            if r + dr >= h:
                                break
                            if grid[r + dr][c] == 9:
                                has_9_down = True

                        if has_9_down:
                            result[r][c] = 2

    return result

