import json

def transform_rule_v3(grid, threshold=3):
    """
    Rule: A 4 becomes 2 if it's between two 9s in the same row OR column,
    AND the maximum distance to a 9 in each direction is ≤ threshold.
    """
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    max_dist = threshold

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                became_2 = False

                # Check horizontal
                has_9_left = False
                for dc in range(1, w):
                    if c - dc < 0:
                        break
                    if grid[r][c - dc] == 9:
                        has_9_left = True
                        c1 = dc
                        break

                if has_9_left:
                    has_9_right = False
                    for dc in range(1, w):
                        if c + dc >= w:
                            break
                        if grid[r][c + dc] == 9:
                            has_9_right = True
                            c2 = dc
                            break

                    if has_9_right and max(c1, c2) <= max_dist:
                        result[r][c] = 2
                        became_2 = True

                if not became_2:
                    # Check vertical
                    has_9_up = False
                    for dr in range(1, h):
                        if r - dr < 0:
                            break
                        if grid[r - dr][c] == 9:
                            has_9_up = True
                            dr_up = dr
                            break

                    if has_9_up:
                        has_9_down = False
                        for dr in range(1, h):
                            if r + dr >= h:
                                break
                            if grid[r + dr][c] == 9:
                                has_9_down = True
                                dr_down = dr
                                break

                        if has_9_down and max(dr_up, dr_down) <= max_dist:
                            result[r][c] = 2

    return result

