# Let me check what 9s are around each mismatch
def get_9_in_direction(grid, r, c, direction):
    """Get list of (distance, col or row) for 9s in a direction"""
    res = []
    if direction == ('L',):
        for dc in range(1, len(grid[0])):
            if c - dc < 0:
                break
            if grid[r][c - dc] == 9:
                res.append((dc, c - dc))
                if dc > 20:  # Avoid very big distances
                    break
    elif direction == ('R',):
        for dc in range(1, len(grid[0])):
            if c + dc >= len(grid[0]):
                break
            if grid[r][c + dc] == 9:
                res.append((dc, c + dc))
                if dc > 20:
                    break
    elif direction == ('U',):
        for dr in range(1, len(grid)):
            if r - dr < 0:
                break
            if grid[r - dr][c] == 9:
                res.append((dr, r - dr))
                if dr > 20:
                    break
    elif direction == ('D',):
        for dr in range(1, len(grid)):
            if r + dr >= len(grid):
                break
            if grid[r + dr][c] == 9:
                res.append((dr, r + dr))
                if dr > 20:
                    break
    return res

