def get_distances(grid, r, c):
    row_left = []
    row_right = []
    col_up = []
    col_down = []

    for dc in range(1, 100):
        if c - dc < 0:
            break
        if grid[r][c - dc] == 9:
            row_left.append(dc)

    for dc in range(1, 100):
        if c + dc >= 15:
            break
        if grid[r][c + dc] == 9:
            row_right.append(dc)

    for dr in range(1, 100):
        if r - dr < 0:
            break
        if grid[r - dr][c] == 9:
            col_up.append(dr)

    for dr in range(1, 100):
        if r + dr >= 12:
            break
        if grid[r + dr][c] == 9:
            col_down.append(dr)

    return {
        'L': row_left, 'R': row_right, 'U': col_up, 'D': col_down,
        'minL': min(row_left) if row_left else None,
        'minR': min(row_right) if row_right else None,
        'minU': min(col_up) if col_up else None,
        'minD': min(col_down) if col_down else None,
    }

def is_between_both(grid, r, c):
    dists = get_distances(grid, r, c)
    horiz_between = dists['minL'] is not None and dists['minR'] is not None
    vert_between = dists['minU'] is not None and dists['minD'] is not None
    return horiz_between or vert_between

