def get_distances(grid, r, c):
    row_left = []
    row_right = []
    col_up = []
    col_down = []

    for dc in range(1, 100):
        if c - dc < 0:
            break
        if grid[r][c - dc] == 9:
            row_left.append(dc)

    for dc in range(1, 100):
        if c + dc >= 15:
            break
        if grid[r][c + dc] == 9:
            row_right.append(dc)

    for dr in range(1, 100):
        if r - dr < 0:
            break
        if grid[r - dr][c] == 9:
            col_up.append(dr)

    for dr in range(1, 100):
        if r + dr >= 12:
            break
        if grid[r + dr][c] == 9:
            col_down.append(dr)

    return {
        'L': row_left, 'R': row_right, 'U': col_up, 'D': col_down,
        'minL': min(row_left) if row_left else None,
        'minR': min(row_right) if row_right else None,
        'minU': min(col_up) if col_up else None,
        'minD': min(col_down) if col_down else None,
    }

def dist_sum(dists):
    """Calculate sum of nearest distances for each valid direction"""
    s = 0
    if dists['minL'] is not None:
        s += dists['minL']
    if dists['minR'] is not None:
        s += dists['minR']
    if dists['minU'] is not None:
        s += dists['minU']
    if dists['minD'] is not None:
        s += dists['minD']
    return s

def is_between_nearest(grid, r, c):
    """Check if cell has 9 on nearest side in row OR column"""
    dists = get_distances(grid, r, c)
    # Check if nearest 9s exist in both directions in same row
    if dists['minL'] is not None and dists['minR'] is not None:
        return True
    # Or in same column
    if dists['minU'] is not None and dists['minD'] is not None:
        return True
    return False

