def sum_max_pairs(grid, r, c):
    """Sum of the two largest distance pairs to 9s"""
    directions = [
        ('L', max_dist_to_9(grid, r, c, 'L')),
        ('R', max_dist_to_9(grid, r, c, 'R')),
