def has_9_in_direction(grid, r, c, direction):
    """Check if there's a 9 in the given direction"""
    if direction == 'L':
        for dc in range(1, c+1):
            if grid[r][c-dc] == 9:
                return True
        return False
    elif direction == 'R':
        for dc in range(1, len(grid[0])-c):
            if grid[r][c+dc] == 9:
                return True
        return False
    elif direction == 'U':
        for dr in range(1, r+1):
            if grid[r-dr][c] == 9:
                return True
        return False
    elif direction == 'D':
        for dr in range(1, len(grid)-r):
            if grid[r+dr][c] == 9:
                return True
        return False
    return False

# New rule: (L>=1 AND R>=1 AND max(L,R)<=3) OR (U>=1 AND D>=1 AND max(U,D)<=3)
def check_both_directions_threshold_3(grid, r, c):
    """4 → 2 if (L AND R both exist AND max_dist <= 3) OR (U AND D both exist AND max_dist <= 3)"""
    if grid[r][c] != 4:
        return False

    l = max_dist_to_9(grid, r, c, 'L')
    r_d = max_dist_to_9(grid, r, c, 'R')
    u = max_dist_to_9(grid, r, c, 'U')
    d = max_dist_to_9(grid, r, c, 'D')

    # Check L+R pair
    if l != 'inf' and r_d != 'inf' and max(l, r_d) <= 3:
        return True
    # Check U+D pair
    if u != 'inf' and d != 'inf' and max(u, d) <= 3:
        return True

    return False

