# Fix smap calculation - only sum finite distances
def analyze_cell2(grid, r, c):
    l = max_dist_to_9(grid, r, c, 'L')
    r_d = max_dist_to_9(grid, r, c, 'R')
    u = max_dist_to_9(grid, r, c, 'U')
    d = max_dist_to_9(grid, r, c, 'D')

    directions_present = []
    for dist, dir_name in [(l, 'L'), (r_d, 'R'), (u, 'U'), (d, 'D')]:
        if dist != 'inf' and dist != float('inf'):
            directions_present.append((dist, dir_name))

    unique_dirs = list(set(dir_name for dist, dir_name in directions_present))
    n_directions = len(unique_dirs)
    smap = sum([dist for dist, dir_name in directions_present])

    return {
        'l': l, 'r_d': r_d, 'u': u, 'd': d,
        'n_directions': n_directions, 'n_cells': len(directions_present),
        'smap': smap,
        'unique_dirs': sorted(unique_dirs),
        'present': directions_present
    }

