                return True
    elif direction == 'R':
        for dc in range(1, len(grid[0])-c):
            if grid[r][c+dc] == 9:
                return True
    elif direction == 'U':
        for dr in range(1, r+1):
            if grid[r-dr][c] == 9:
                return True
    elif direction == 'D':
        for dr in range(1, len(grid)-r):
            if grid[r+dr][c] == 9:
                return True
    return False

def check_bracketed(grid, r, c):
    """4 → 2 if exactly ONE bracket type exists (horizontal XOR vertical)"""
    if grid[r][c] != 4:
        return False, 0

    has_h = has_9_in_direction(grid, r, c, 'L') and has_9_in_direction(grid, r, c, 'R')
    has_v = has_9_in_direction(grid, r, c, 'U') and has_9_in_direction(grid, r, c, 'D')

    # True positives: exactly one bracket type (not both)
    is_bracketed = has_h or has_v
    double = has_h and has_v

    return is_bracketed, double

